class MakeFileTarget:
    """manages a target in a makefile"""

    _TAB = "\t"
    _default_silent = False
    _order_num = 999
    _identifier = "GENERIC"

    # GROUP_IDENTIFIER = _MFIdentifier.get("GENERIC")

    def __init__(self, name, dependencies=None, silent=None):
        self._name = name
        self._path = "."
        if dependencies is None:
            dependencies = []
        for dep in dependencies:
            if not isinstance(dep, MakeFileTarget):
                raise TypeError("dep must be an instance of MakeFileTarget")
        self._dependencies = dependencies
        if silent is None:
            self._silent = type(self)._default_silent

    def __init_subclass__(
        cls,
        order=None,
        identifier=None,
        silent=None,
    ):
        if order is None:
            order = cls._order_num
        cls._order_num = order
        if identifier is None:
            identifier = cls.__name__
        cls._identifier = identifier
        if silent is None:
            silent = cls._default_silent
        cls._default_silent = silent

    @property
    def name(self):
        """read-only access to name"""
        return self._name

    @property
    def path(self):
        """read-only access to path"""
        return self._path

    @property
    def dependencies(self):
        """read-only access to dependencies"""
        yield from self._dependencies

    @property
    def is_silent(self):
        """access silent state of the target"""
        return self._silent

    @classmethod
    def get_target_identifier(cls):
        """get a group identifier"""
        return cls._identifier

    def get_dependencies(self, recursive=True):
        """recursively get all depenendcies"""
        for dep in self.dependencies:
            if recursive:
                yield from dep.get_dependencies(recursive=True)
            yield dep

    @property
    def class_rank(self):
        """access the classes order number"""
        return type(self)._order_num

    @property
    def _sort_hash(self):
        return (
            self.class_rank,
            len(no_duplicates(self.get_dependencies(recursive=True))),
            self.target_name(),
        )

    def __eq__(self, other):
        return self.target_name() == other.target_name()

    def __gt__(self, other):
        return self._sort_hash > other._sort_hash
        # if self.class_rank < other.class_rank:
        #     return False
        # if self.class_rank > other.class_rank:
        #     return True
        # return self.target_name() > other.target_name()

    def target_name(self):
        """get the proper target name"""
        return self.name

    def include_as(self):
        """get the proper elements how to include the target"""
        return self.name

    def get_incdir_contributions(self):
        """get the include directory path"""
        return
        yield

    def get_libdir_contributions(self):
        """get the library directory path"""
        return
        yield

    def get_loclib_contributions(self):
        """get local libs"""
        return
        yield

    def get_extlib_contributions(self):
        """get external libs"""
        return
        yield

    def get_scfile_contributions(self):
        """get source"""
        return
        yield

    def get_obfile_contributions(self):
        """get object files"""
        return
        yield

    def get_hdfile_contributions(self):
        """get header files"""
        return
        yield

    def target_get_makefile_lines(self):
        """get the lines that have to be appended in the makefile"""
        depnames = " ".join(dep.target_name() for dep in self.dependencies)
        yield f"{self.target_name()}: {depnames}"
        for line in self.generate():
            if line is not None:
                yield f"{type(self)._TAB}" + line

    def generate(self, *flags):
        """get the lines that actually generate the target"""
        flags = list(flags)
        return
        yield

    def summarize_contributions(self):
        """generate the include dirs, lib dirs and the line for dependencies required"""
        loclibs = []
        extlibs = []
        scfiles = []
        obfiles = []
        hdfiles = []
        incdirs = []
        libdirs = []
        for dep in self.dependencies:
            loclibs.extend(list(dep.get_loclib_contributions()))
            extlibs.extend(list(dep.get_extlib_contributions()))
            scfiles.extend(list(dep.get_scfile_contributions()))
            obfiles.extend(list(dep.get_obfile_contributions()))
            hdfiles.extend(list(dep.get_hdfile_contributions()))
            incdirs.extend(list(dep.get_incdir_contributions()))
            libdirs.extend(list(dep.get_libdir_contributions()))
        loclibs = no_duplicates(loclibs)
        extlibs = no_duplicates(extlibs)
        scfiles = no_duplicates(scfiles)
        obfiles = no_duplicates(obfiles)
        hdfiles = no_duplicates(hdfiles)
        incdirs = no_duplicates(incdirs)
        libdirs = no_duplicates(libdirs)
        return {
            "loclibs": loclibs,
            "extlibs": extlibs,
            "scfiles": scfiles,
            "obfiles": obfiles,
            "hdfiles": hdfiles,
            "incdirs": incdirs,
            "libdirs": libdirs,
        }


